'use strict';
const $=id=>document.getElementById(id);
const stages=[{name:'Novo lead',prob:.1,color:'#9baaa1'},{name:'Contato',prob:.25,color:'#6c9fc0'},{name:'Proposta',prob:.5,color:'#beab60'},{name:'Negociação',prob:.75,color:'#b08cb5'},{name:'Ganho',prob:1,color:'#6ca553'},{name:'Perdido',prob:0,color:'#bf7d69'}];
const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(v);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const seed=[['Marina Costa','Aurora Design',4200,0,'Fernando'],['Pedro Nunes','Nexo Digital',6800,0,'Ana'],['Beatriz Lima','Estúdio Forma',3500,1,'Fernando'],['Rafael Alves','Vértice Tech',12000,1,'Ana'],['Camila Rocha','Orbe Educação',8500,2,'Fernando'],['Lucas Mendes','Atlas Logística',15000,2,'Ana'],['Juliana Freitas','Vitta Saúde',9600,3,'Fernando'],['André Souza','Lumina Soluções',7200,3,'Ana'],['Clara Santos','Norte Consultoria',5400,4,'Fernando'],['Diego Martins','Íris Comunicação',7800,4,'Ana'],['Paula Ribeiro','Mosaico Studio',3200,4,'Fernando'],['Bruno Dias','Ponto Retail',4600,5,'Ana']];
let leads=seed.map((r,i)=>({id:crypto.randomUUID(),name:r[0],company:r[1],value:r[2],stage:r[3],owner:r[4],email:`contato${i+1}@example.com`,phone:'',date:'',notes:'Oportunidade fictícia para demonstração.'}));
let source='Demonstração',dirty=false,pending=null;
function metrics(data){const open=data.filter(l=>l.stage<4),won=data.filter(l=>l.stage===4),lost=data.filter(l=>l.stage===5);return {pipeline:open.reduce((s,l)=>s+l.value,0),forecast:open.reduce((s,l)=>s+l.value*stages[l.stage].prob,0),conversion:won.length+lost.length?won.length/(won.length+lost.length)*100:null,ticket:won.length?won.reduce((s,l)=>s+l.value,0)/won.length:null,open:open.length,won:won.length,lost:lost.length};}
function render(){
 const m=metrics(leads);$('metrics').innerHTML=[['Pipeline aberto',money(m.pipeline),`${m.open} oportunidades em andamento`],['Previsão ponderada',money(m.forecast),'Estimativa sobre negócios abertos'],['Conversão',m.conversion===null?'—':m.conversion.toFixed(1).replace('.',',')+'%',`${m.won} ganhos · ${m.lost} perdidos`],['Ticket médio',m.ticket===null?'—':money(m.ticket),'Valor médio dos negócios ganhos']].map(r=>`<article class="metric"><p>${r[0]}</p><strong>${r[1]}</strong><small>${r[2]}</small></article>`).join('');
 const owner=$('owner').value;const owners=[...new Set(leads.map(l=>l.owner).filter(Boolean))].sort();$('owner').innerHTML='<option value="">Todos os responsáveis</option>'+owners.map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('');$('owner').value=owners.includes(owner)?owner:'';
 const term=norm($('search').value);const shown=leads.filter(l=>(!$('owner').value||l.owner===$('owner').value)&&norm([l.name,l.company,l.email,l.phone].join(' ')).includes(term));
 $('count').textContent=`${shown.length} de ${leads.length} oportunidades · ${source}`;$('mode').textContent=source;
 const today=new Date().toLocaleDateString('en-CA');
 $('board').innerHTML=stages.map((s,i)=>{const rows=shown.filter(l=>l.stage===i);return `<section class="column" style="--stage:${s.color}"><div class="col-head"><strong>${s.name}</strong><span>${rows.length}</span></div><p class="col-total">${money(rows.reduce((a,l)=>a+l.value,0))}</p>${rows.map(l=>`<button class="card" data-edit="${l.id}"><span class="company">${esc(l.company||'Sem empresa')}</span><strong>${esc(l.name)}</strong><span class="amount">${money(l.value)}</span><span class="card-bottom"><span>${esc(l.owner||'Sem responsável')}</span>${l.date?`<span class="${l.date<today&&l.stage<4?'due':''}">${l.date<today&&l.stage<4?'Atrasado · ':''}${l.date.split('-').reverse().join('/')}</span>`:''}</span></button>`).join('')||'<p class="empty">Nenhuma oportunidade nesta etapa.</p>'}</section>`}).join('');
 $('table').innerHTML=`<table><thead><tr>${['Contato','Empresa','Valor','Etapa','Responsável','Próximo contato','Ação'].map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${shown.map(l=>`<tr><td>${esc(l.name)}<br><small>${esc(l.email||l.phone)}</small></td><td>${esc(l.company)}</td><td>${money(l.value)}</td><td>${stages[l.stage].name}</td><td>${esc(l.owner)}</td><td>${l.date?l.date.split('-').reverse().join('/'):'—'}</td><td><button data-edit="${l.id}">Editar</button></td></tr>`).join('')||'<tr><td colspan="7">Nenhuma oportunidade encontrada. Limpe os filtros ou importe seu CSV.</td></tr>'}</tbody></table>`;
}
function edit(id){const l=leads.find(l=>l.id===id);const f=$('editForm');f.reset();$('editTitle').textContent=l?'Editar oportunidade':'Nova oportunidade';for(const key of ['id','name','company','email','phone','value','stage','owner','date','notes'])f.elements.namedItem(key).value=l?l[key]:key==='value'||key==='stage'?0:'';$('editDialog').showModal();}
$('stageOptions').innerHTML=stages.map((s,i)=>`<option value="${i}">${s.name}</option>`).join('');
$('new').onclick=()=>edit();document.addEventListener('click',e=>{const editBtn=e.target.closest('[data-edit]'),close=e.target.closest('[data-close]');if(editBtn)edit(editBtn.dataset.edit);if(close)$(close.dataset.close).close();});
$('editForm').onsubmit=e=>{e.preventDefault();const raw=Object.fromEntries(new FormData(e.target));raw.name=raw.name.trim();if(!raw.name){e.target.elements.namedItem('name').setCustomValidity('Informe um nome.');e.target.reportValidity();return;}raw.value=Number(raw.value);raw.stage=Number(raw.stage);if(!Number.isFinite(raw.value)||raw.value<0||raw.value>1e12||!Number.isInteger(raw.stage)||raw.stage<0||raw.stage>5)return;const index=leads.findIndex(l=>l.id===raw.id);raw.id=raw.id||crypto.randomUUID();if(index<0)leads.push(raw);else leads[index]=raw;dirty=true;$('editDialog').close();render();$('status').textContent='Oportunidade salva nesta sessão. Exporte o CSV para guardar suas alterações.';};
$('editForm').elements.namedItem('name').addEventListener('input',e=>e.target.setCustomValidity(''));
$('search').oninput=render;$('owner').onchange=render;$('clear').onclick=()=>{$('search').value='';$('owner').value='';render();};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));$('board').hidden=b.dataset.view!=='board';$('table').hidden=b.dataset.view!=='table';});
function parseCSV(text){text=text.replace(/^\uFEFF/,'');let quoted=false,counts={',':0,';':0,'\t':0};for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){i++;continue;}quoted=!quoted;}else if(!quoted&&(c==='\r'||c==='\n'))break;else if(!quoted&&c in counts)counts[c]++;}const delimiter=Object.keys(counts).sort((a,b)=>counts[b]-counts[a])[0];const rows=[];let row=[],cell='';quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(quoted||!cell)quoted=!quoted;else cell+=c;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if((c==='\r'||c==='\n')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Há aspas sem fechamento no CSV.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(rows.length<2)throw Error('Inclua cabeçalhos e pelo menos um lead.');const headers=rows.shift().map((v,i)=>v.trim()||`Coluna ${i+1}`);if(rows.some(r=>r.length!==headers.length))throw Error('Há linhas com quantidade diferente de colunas. Revise o CSV.');if(rows.length>10000)throw Error('Importe no máximo 10.000 leads por arquivo.');return {headers,rows};}
function parseValue(raw){let s=String(raw).replace(/R\$|\s/g,'');if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');else if(/^\d{1,3}(\.\d{3})+$/.test(s))s=s.replace(/\./g,'');const n=Number(s);return Number.isFinite(n)&&n>=0&&n<=1e12?n:0;}
const fields=[['name','Nome do contato',['nome','name','cliente','contato','nome completo','nome do contato','lead']],['company','Empresa',['empresa','company','razao social']],['email','E-mail',['email','e-mail']],['phone','Telefone',['telefone','phone','celular','whatsapp']],['value','Valor',['valor','value','valor (r$)','valor da oportunidade']],['stage','Etapa',['etapa','stage','status']],['owner','Responsável',['responsavel','owner','vendedor']],['date','Próximo contato',['proximo contato','data','date']],['notes','Observações',['observacoes','notes','notas']]];
$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('Use um CSV de até 5 MB.');const b=await file.arrayBuffer();let text=new TextDecoder().decode(b);if(text.includes('\uFFFD'))text=new TextDecoder('windows-1252').decode(b);pending=parseCSV(text);$('fileInfo').textContent=`${file.name} · ${pending.rows.length} leads encontrados`;$('mapping').innerHTML=fields.map(([key,label,aliases])=>{const found=pending.headers.findIndex(h=>aliases.includes(norm(h)));return `<label>${label}<select name="${key}" ${key==='name'?'required':''}><option value="">${key==='name'?'Selecione a coluna':'Não importar'}</option>${pending.headers.map((h,i)=>`<option value="${i}" ${i===found?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`}).join('');$('importError').textContent='';$('importDialog').showModal();}catch(err){$('status').textContent=err.message;}e.target.value='';};
function validDate(v){let s=v.trim();if(/^\d{2}\/\d{2}\/\d{4}$/.test(s))s=s.split('/').reverse().join('-');if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return '';const d=new Date(s+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===s?s:'';}
$('importForm').onsubmit=e=>{e.preventDefault();const mapping=Object.fromEntries(new FormData(e.target));const selected=Object.values(mapping).filter(v=>v!=='');if(new Set(selected).size!==selected.length){$('importError').textContent='Use cada coluna apenas uma vez.';return;}if(dirty&&!confirm('A importação substituirá suas alterações. Já exportou o que deseja guardar?'))return;let skipped=0;const next=pending.rows.map(row=>{const get=k=>mapping[k]===''?'':row[Number(mapping[k])].trim();if(!get('name')){skipped++;return null;}const stage=stages.findIndex(s=>norm(s.name)===norm(get('stage')));return {id:crypto.randomUUID(),name:get('name'),company:get('company'),email:get('email'),phone:get('phone'),value:parseValue(get('value')),stage:stage<0?0:stage,owner:get('owner'),date:validDate(get('date')),notes:get('notes')};}).filter(Boolean);if(!next.length){$('importError').textContent='Nenhum lead tem nome na coluna selecionada.';return;}leads=next;source='Carteira importada';dirty=true;$('search').value='';$('owner').value='';$('importDialog').close();render();$('status').textContent=`${next.length} leads importados. ${skipped} linhas sem nome ignoradas. Confira valores e etapas antes de usar a previsão.`;pending=null;};
$('export').onclick=()=>{const rows=[fields.map(f=>f[1]),...leads.map(l=>[l.name,l.company,l.email,l.phone,l.value.toFixed(2).replace('.',','),stages[l.stage].name,l.owner,l.date,l.notes])];const quote=v=>'"'+String(v).replace(/^[=+@\t\r-]/,"'$&").replace(/"/g,'""')+'"';const csv='\uFEFF'+rows.map(r=>r.map(quote).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='pulse-sales-carteira.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='Download solicitado. Confira o arquivo na pasta Downloads antes de fechar esta página.';};
$('demo').onclick=()=>{if(confirm('Restaurar os exemplos fictícios? Exporte antes se quiser guardar a carteira atual.')){dirty=false;location.reload();}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});render();
